let _markdown = "\n\nSetup [#setup]\n\n<FeedbackBlock id=\"8dc0a161861fb7d7\" body=\"You can create the feed object:\">\n  You can create the feed object:\n</FeedbackBlock>\n\n```ts title=\"lib/rss.ts\"\nimport { Feed } from 'feed';\nimport { source } from '@/lib/source';\n\nconst baseUrl = 'https://fumadocs.dev';\n\nexport function getRSS() {\n  const feed = new Feed({\n    title: 'Fumadocs Blog',\n    id: `${baseUrl}/blog`,\n    link: `${baseUrl}/blog`,\n    language: 'en',\n\n    image: `${baseUrl}/banner.png`,\n    favicon: `${baseUrl}/icon.png`,\n    copyright: 'All rights reserved 2025, Fuma Nama',\n  });\n\n  for (const page of source.getPages()) {\n    feed.addItem({\n      id: page.url,\n      title: page.data.title,\n      description: page.data.description,\n      link: `${baseUrl}${page.url}`,\n      date: new Date(page.data.lastModified),\n\n      author: [\n        {\n          name: 'Fuma',\n        },\n      ],\n    });\n  }\n\n  return feed.rss2();\n}\n```\n\n<FeedbackBlock id=\"5651bf4b08198e4e\" body=\"And expose it using a server loader/route handler like:\">\n  And expose it using a server loader/route handler like:\n</FeedbackBlock>\n\n<CodeBlockTabs defaultValue=\"Next.js\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"Next.js\">\n      Next.js\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"React Router\">\n      React Router\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"Tanstack Start\">\n      Tanstack Start\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"Next.js\">\n    ```ts  title=\"app/rss.xml/route.ts\"\n    import { getRSS } from '@/lib/rss';\n\n    export const revalidate = false;\n\n    export function GET() {\n      return new Response(getRSS());\n    }\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"React Router\">\n    ```ts\n    // app/routes/rss.ts\n    import { getRSS } from '@/lib/rss';\n\n    export async function loader() {\n      return new Response(getRSS());\n    }\n\n    // app/routes.ts\n    import { route, type RouteConfig } from '@react-router/dev/routes';\n\n    export default [\n      // ...\n      route('rss.xml', 'routes/rss.ts'),\n    ] satisfies RouteConfig;\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"Tanstack Start\">\n    ```ts  title=\"src/routes/rss[.]xml.ts\"\n    import { createFileRoute } from '@tanstack/react-router';\n    import { getRSS } from '@/lib/rss';\n\n    export const Route = createFileRoute('/rss.xml')({\n      server: {\n        handlers: {\n          GET: async () => new Response(getRSS()),\n        },\n      },\n    });\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n\nNext.js Metadata [#nextjs-metadata]\n\n<FeedbackBlock id=\"983392945b9568a4\" body=\"You can add an alternates object to the metadata object with your feed’s title and URL.\">\n  You can add an alternates object to the metadata object with your feed’s title and URL.\n</FeedbackBlock>\n\n```ts title=\"app/layout.tsx\"\nimport type { Metadata } from 'next';\n\nexport const metadata: Metadata = {\n  alternates: {\n    types: {\n      'application/rss+xml': [\n        {\n          title: 'Fumadocs Blog',\n          url: 'https://fumadocs.dev/blog/index.xml',\n        },\n      ],\n    },\n  },\n};\n```\n";
